const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/query-record.cjs');
test('object constructor coercion and encoding', () => {
  for (const [record, expected] of [
    [{tag:['red','blue'],q:'a b'}, 'tag=red%2Cblue&q=a+b'],
    [{tag:[],enabled:false,page:0}, 'tag=&enabled=false&page=0'],
    [{'x y':['a&b','c+d']}, 'x+y=a%26b%2Cc%2Bd'],
    [{note:'~!*'}, 'note=%7E%21*'], [{}, '']
  ]) {
    const before = JSON.stringify(record);
    assert.equal(app.queryRecord(record),expected);
    assert.equal(JSON.stringify(record),before);
  }
});

