const test = require('node:test');
const assert = require('node:assert/strict');
const { queryRecord } = require('../lib/query-record.cjs');
test('optional sorting retains the first-round object conversion', () => {
  const record = {z:['red','blue'], a:'a b', A:'~'};
  const before = JSON.stringify(record);
  assert.equal(queryRecord(record), 'z=red%2Cblue&a=a+b&A=%7E');
  assert.equal(queryRecord(record, false), 'z=red%2Cblue&a=a+b&A=%7E');
  assert.equal(queryRecord(record, true), 'A=%7E&a=a+b&z=red%2Cblue');
  assert.equal(JSON.stringify(record), before);
  // UTF-16 ordering differs from code point ordering for these keys.
  assert.equal(queryRecord({'\uE000':'bmp','😀':'astral'}, true), '%F0%9F%98%80=astral&%EE%80%80=bmp');
  assert.equal(queryRecord({}, true), '');
});

